create function touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create table responders(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null check(length(trim(name))>0),active boolean not null default true,review_due date not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table policies(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,owner text not null default '',levels integer not null default 2 check(levels between 1 and 10),review_due date not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table services(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,policy_id uuid not null references policies(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table slots(id uuid primary key default gen_random_uuid(),code text unique not null,policy_id uuid not null references policies(id),responder_id uuid not null references responders(id),level integer not null check(level between 1 and 10),schedule text not null default 'Direct assignment',starts_at timestamptz not null,ends_at timestamptz not null,verified boolean not null default false,evidence text not null default '',raw jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at));
create index slots_window on slots(starts_at,ends_at);
create table handovers(id uuid primary key default gen_random_uuid(),code text unique not null,policy_id uuid not null references policies(id),name text not null,owner text not null,due_at timestamptz not null,status text not null default 'open' check(status in ('open','done')),evidence text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(status <> 'done' or length(trim(evidence))>0));
create table actions(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,owner text not null,due_on date not null,status text not null default 'open' check(status in ('open','done')),evidence text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(status <> 'done' or length(trim(evidence))>0));
create table imports(id uuid primary key default gen_random_uuid(),source text not null,sha256 text not null,records integer not null,actor text not null,created_at timestamptz not null default now(),unique(source,sha256));
create table audit(id uuid primary key default gen_random_uuid(),actor text not null,operation text not null,record text not null,evidence text not null,created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['responders','policies','services','slots','handovers','actions'] loop execute format('create trigger touch before update on %I for each row execute function touch_updated_at()',t); end loop; foreach t in array array['responders','policies','services','slots','handovers','actions','imports','audit'] loop execute format('alter table %I enable row level security',t); execute format('revoke all on %I from public',t); end loop; end $$;
create view v_roster as select s.id,s.code,p.code policy_code,p.name policy,r.code responder_code,r.name responder,r.active,s.level,s.schedule,s.starts_at,s.ends_at,s.verified,s.evidence from slots s join policies p on p.id=s.policy_id join responders r on r.id=s.responder_id;
create view v_attention as
 select 'unverified-slot' reason,code,name,owner,due from (select s.code,p.name,''::text owner,s.starts_at::text due from slots s join policies p on p.id=s.policy_id where not s.verified and s.ends_at>now()) x
 union all select 'policy-review',code,name,owner,review_due::text from policies where review_due<current_date or owner=''
 union all select 'retention-review',code,name,'',review_due::text from responders where review_due<current_date
 union all select 'handover-overdue',code,name,owner,due_at::text from handovers where status='open' and due_at<now()
 union all select 'action-overdue',code,name,owner,due_on::text from actions where status='open' and due_on<current_date;
create view v_week as select p.code,p.name,p.owner,p.levels,count(distinct s.id)::int assignments,count(distinct s.responder_id)::int responders from policies p left join slots s on s.policy_id=p.id and s.ends_at>current_date and s.starts_at<current_date+interval '7 days' group by p.id;
revoke all on v_roster,v_attention,v_week from public;
